const crypto = require('crypto');

// ── CONFIGURE THESE ──────────────────────────────────────────────────
const HMAC_SECRET = 'CHANGE_THIS_TO_YOUR_SECRET_KEY_MIN_32_CHARS';
const N8N_BASE    = 'https://n8n-giez.srv1499541.hstgr.cloud';
const PHOTOGRAPHER_EMAIL = 'info@silverframe.hu';
// ─────────────────────────────────────────────────────────────────────

const item = $input.first().json;

// Generate unique booking ID
const bookingId = crypto.randomUUID();

// Build canonical booking object
const booking = {
  id:          bookingId,
  service:     item.service     || '',
  serviceName: item.serviceName || item.service || 'Fotózás',
  bookingType: item.bookingType || 'hourly',
  date:        item.date        || '',
  endDate:     item.endDate     || null,
  time:        item.time        || null,
  duration:    item.duration    || 2,
  name:        item.name        || '',
  email:       item.email       || '',
  phone:       item.phone       || '',
  note:        item.note        || '',
  source:      item.source      || 'website',
  createdAt:   new Date().toISOString(),
  draftEmail:  null,
  calendarEventId: null,
  calendarConflict: item.calendarConflict || false,
  conflictDetails:  item.conflictDetails  || null
};

// Persist booking in workflow static data
const sd = $getWorkflowStaticData('global');
if (!sd.bookings) sd.bookings = {};
sd.bookings[bookingId] = booking;

// HMAC token — signs the bookingId so links can't be forged
const token = crypto.createHmac('sha256', HMAC_SECRET).update(bookingId).digest('hex');

// Human-readable date string
let dateDisplay = booking.date;
if (booking.endDate) dateDisplay += ' → ' + booking.endDate;
if (booking.time)    dateDisplay += ' ' + booking.time;

// ── Google Calendar datetime calculation ─────────────────────────────
let startDateTime, endDateTime, isAllDay = false;

if (booking.bookingType === 'hourly' && booking.time) {
  const dur = parseInt(booking.duration) || 2;
  const start = new Date(booking.date + 'T' + booking.time + ':00');
  const end   = new Date(start.getTime() + dur * 3600000);
  startDateTime = start.toISOString();
  endDateTime   = end.toISOString();
} else if (booking.bookingType === 'multiday' && booking.endDate) {
  isAllDay = true;
  startDateTime = booking.date;
  const endD = new Date(booking.endDate + 'T12:00:00');
  endD.setDate(endD.getDate() + 1);
  endDateTime = endD.toISOString().split('T')[0];
} else {
  // fullday
  isAllDay = true;
  startDateTime = booking.date;
  const nextD = new Date(booking.date + 'T12:00:00');
  nextD.setDate(nextD.getDate() + 1);
  endDateTime = nextD.toISOString().split('T')[0];
}

// Action URLs for the 5 approval buttons
const base = N8N_BASE + '/webhook/action';
const q    = `bookingId=${bookingId}&token=${token}`;

// Calendar availability badge
const conflictBadgeClass = booking.calendarConflict ? 'conflict' : '';
const conflictText = booking.calendarConflict
  ? `⚠️ FIGYELEM: Ütközés! ${booking.conflictDetails || 'Ez az időpont már foglalt a naptárban.'}`
  : '✅ Az időpont szabad a naptárban';

// Gemini prompt for drafting the client email
const firstName = booking.name.split(' ').slice(-1)[0]; // last word = first name in Hungarian
const geminiPrompt = `Írj egy rövid, professzionális és barátságos e-mailt egy fotózásos foglalásra reagálva. Az email célja: tájékoztasd az ügyfelet, hogy a kérelme megérkezett, és hamarosan visszaigazolják.

Foglalás adatok:
- Ügyfél neve: ${booking.name}
- Szolgáltatás: ${booking.serviceName}
- Dátum: ${dateDisplay}
- Megjegyzés az ügyféltől: ${booking.note || '(nincs)'}
- Forrás: ${booking.source}

Elvárások:
- Magyar nyelven írj
- Szólítsd meg az ügyfelet keresztnéven: ${firstName}
- Köszönd meg az érdeklődést
- Mondd hogy a kérelem megérkezett, István hamarosan visszaigazol (24 órán belül)
- Ha van megjegyzés, reagálj rá 1 mondatban
- Elérhetőség ha sürgős: info@silverframe.hu vagy WhatsApp +36 20 379 9814
- Aláírás: "Üdvözlettel,\nIstván\nSilverframe Studio"
- Maximum 120 szó
- NE adj árat
- Csak a levél szövege, semmi más`;

return [{
  json: {
    ...booking,
    token,
    bookingId,
    dateDisplay,
    startDateTime,
    endDateTime,
    isAllDay,
    calendarTitle: `[FOGLALÁS] ${booking.serviceName} – ${booking.name}`,
    calendarDescription: `Ügyfél: ${booking.name}\nEmail: ${booking.email}\nTelefon: ${booking.phone}\nMegjegyzés: ${booking.note}\nForrás: ${booking.source}\nID: ${bookingId}`,
    conflictBadgeClass,
    conflictText,
    geminiPrompt,
    approveUrl:    `${base}?${q}&action=approve`,
    editUrl:       `${base}?${q}&action=edit`,
    regenUrl:      `${base}?${q}&action=regen`,
    rescheduleUrl: `${base}?${q}&action=reschedule`,
    rejectUrl:     `${base}?${q}&action=reject`,
    photographerEmail: PHOTOGRAPHER_EMAIL
  }
}];

const item = $input.first().json;
const bookingId = item.id;

// Update static data with calendar event ID
const sd = $getWorkflowStaticData('global');
if (sd.bookings && sd.bookings[bookingId]) {
  sd.bookings[bookingId].calendarEventId = item.id_calEvent || item.id || null;
}

// Pass through all data
return [{ json: item }];

const geminiResp = $input.first().json;

// Extract generated text from Gemini response
let draftText = '';
try {
  draftText = geminiResp.candidates[0].content.parts[0].text;
} catch(e) {
  draftText = 'Kedves Ügyfél,\n\nKöszönjük a foglalási kérelmedet! A részletek megérkeztek, István hamarosan visszaigazol 24 órán belül.\n\nÜdvözlettel,\nIstván\nSilverframe Studio';
}

// Pull the booking data (passed upstream via all nodes)
// Walk back to the generate-booking node output
const booking = $('Generate Booking ID & Token').first().json;

// Persist draft email in static data
const sd = $getWorkflowStaticData('global');
if (sd.bookings && sd.bookings[booking.bookingId]) {
  sd.bookings[booking.bookingId].draftEmail = draftText;
}

// ── Build the HTML approval email ────────────────────────────────────
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const escAttr = s => String(s || '').replace(/"/g,'&quot;');

const conflictSection = booking.calendarConflict
  ? `<div class="alert-conflict">
      <strong>⚠️ NAPTÁR ÜTKÖZÉS!</strong><br>
      ${esc(booking.conflictDetails || 'Ez az időpont már foglalt a naptárban.')}
    </div>`
  : `<div class="alert-free">✅ Az időpont szabad a naptárban</div>`;

const sourceLabel = booking.source === 'email' ? '📧 Email' : booking.source === 'chat' ? '💬 Chatbot' : '🌐 Weboldal';

const noteRow = booking.note
  ? `<tr><td class="label">Megjegyzés</td><td class="value">${esc(booking.note)}</td></tr>`
  : '';

const draftHtml = esc(draftText).replace(/\n/g, '<br>');

const html = `<!DOCTYPE html>
<html lang="hu">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body{margin:0;padding:20px;background:#0b0c10;font-family:Arial,sans-serif;color:#e8e4dc}
  .wrap{max-width:620px;margin:0 auto;background:#14151a;border-radius:12px;overflow:hidden}
  .hdr{background:#b8a98a;padding:22px 28px}
  .hdr h1{margin:0;color:#0b0c10;font-size:1.25rem;font-weight:600}
  .body{padding:28px}
  .alert-free{display:inline-block;background:#1a3a1a;color:#66bb6a;padding:6px 16px;border-radius:20px;font-size:.85rem;margin-bottom:18px;border:1px solid #2e7d32}
  .alert-conflict{display:inline-block;background:#3a1a1a;color:#ef5350;padding:6px 16px;border-radius:20px;font-size:.85rem;margin-bottom:18px;border:1px solid #c62828}
  .table{width:100%;border-collapse:collapse;margin-bottom:22px;background:#1a1b20;border-radius:8px;overflow:hidden}
  .table td{padding:10px 14px;border-bottom:1px solid #2a2b30;font-size:.9rem;vertical-align:top}
  .table tr:last-child td{border-bottom:none}
  .label{color:#8a8680;width:110px}
  .value{color:#e8e4dc;font-weight:500}
  .draft{background:#1a1b20;border-left:3px solid #b8a98a;border-radius:0 8px 8px 0;padding:18px;margin-bottom:24px}
  .draft h3{margin:0 0 10px;color:#b8a98a;font-size:.8rem;text-transform:uppercase;letter-spacing:.08em}
  .draft p{margin:0;color:#c8c4bc;line-height:1.7;font-size:.92rem}
  .actions{display:grid;gap:10px}
  .btn{display:block;text-align:center;padding:14px 16px;border-radius:8px;text-decoration:none;font-size:.92rem;font-weight:600;letter-spacing:.02em}
  .btn-approve{background:#1b3a1b;color:#66bb6a;border:1.5px solid #388e3c}
  .btn-edit{background:#1a2a3a;color:#64b5f6;border:1.5px solid #1565c0}
  .btn-regen{background:#1a2a3a;color:#80cbc4;border:1.5px solid #00796b}
  .btn-reschedule{background:#2a2a1a;color:#ffd54f;border:1.5px solid #f57f17}
  .btn-reject{background:#3a1a1a;color:#ef5350;border:1.5px solid #c62828}
  .ftr{padding:16px 28px;border-top:1px solid #222;font-size:.78rem;color:#555;text-align:center}
</style>
</head>
<body>
<div class="wrap">
  <div class="hdr"><h1>📸 Silverframe — Új foglalás érkezett</h1></div>
  <div class="body">
    ${conflictSection}
    <table class="table">
      <tr><td class="label">Ügyfél neve</td><td class="value">${esc(booking.name)}</td></tr>
      <tr><td class="label">Email</td><td class="value">${esc(booking.email)}</td></tr>
      <tr><td class="label">Telefon</td><td class="value">${esc(booking.phone)}</td></tr>
      <tr><td class="label">Szolgáltatás</td><td class="value">${esc(booking.serviceName)}</td></tr>
      <tr><td class="label">Időpont</td><td class="value">${esc(booking.dateDisplay)}</td></tr>
      <tr><td class="label">Forrás</td><td class="value">${sourceLabel}</td></tr>
      ${noteRow}
    </table>
    <div class="draft">
      <h3>AI által előkészített válasz az ügyfélnek</h3>
      <p>${draftHtml}</p>
    </div>
    <div class="actions">
      <a href="${escAttr(booking.approveUrl)}" class="btn btn-approve">✅ &nbsp;Jóváhagyás — Küld az ügyfélnek</a>
      <a href="${escAttr(booking.editUrl)}" class="btn btn-edit">✏️ &nbsp;Szöveg szerkesztése előtte</a>
      <a href="${escAttr(booking.regenUrl)}" class="btn btn-regen">🔄 &nbsp;Újragenerálás saját utasítással</a>
      <a href="${escAttr(booking.rescheduleUrl)}" class="btn btn-reschedule">📅 &nbsp;Elutasítás + Új időpont ajánlása ügyfélnek</a>
      <a href="${escAttr(booking.rejectUrl)}" class="btn btn-reject">❌ &nbsp;Teljes elutasítás (udvarias visszautasítás)</a>
    </div>
  </div>
  <div class="ftr">Silverframe Studio · info@silverframe.hu · Foglalás ID: ${esc(booking.bookingId)}</div>
</div>
</body>
</html>`;

return [{
  json: {
    toEmail: booking.photographerEmail,
    subject: `[FOGLALÁS] ${booking.serviceName} — ${booking.name} (${booking.date})`,
    html,
    bookingId: booking.bookingId,
    clientEmail: booking.email,
    clientName: booking.name
  }
}];
